 * @param {string} locale - The locale code (e.g., 'en', 'hi', 'zh-cn').
 * @param {string} format - The format string (e.g., 'LLLL', 'LTS').
 * @returns {string} The formatted date string.
 */
function formatDateTime(dateString, locale, format) {
    try {
        // Set the locale and parse the date
        moment.locale(locale);
        const date = moment(dateString, 'YYYY-MM-DD HH:mm:ss', true);

        if (!date.isValid()) {
            return `Error: Invalid date string provided for locale ${locale}.`;
        }

        // Format and return the result
        return date.format(format);
    } catch (e) {
        console.error(`Error formatting date for locale ${locale}:`, e);
        return `Error processing date.`;
    }
}

/**
 * Calculates and returns the relative time string for a given time difference.
 * @param {Date} futureDate - The future date/time.
 * @param {Date} pastDate - The past date/time.
 * @param {string} locale - The locale code.
 * @returns {string} The relative time string.
 */
function getRelativeTime(futureDate, pastDate, locale) {
    try {
        moment.locale(locale);

        // Calculate the time difference (milliseconds)
        const diffMs = futureDate.getTime() - pastDate.getTime();
        const diffMoment = moment(diffMs);

        // The moment.fromNow() method handles the relative time formatting based on the locale.
        return moment(diffMs).fromNow();
    } catch (e) {
        console.error(`Error calculating relative time for locale ${locale}:`, e);
        return 'Time calculation error.';
    }
}

